import java.io.*;
import java.util.*;

public class C421 {
    public static void main(String[] args) {
        DataInputStream dis = new DataInputStream(System.in);
        try {
            int a = readInt(dis);
            int b = readInt(dis);
            int l = readInt(dis) - 1;
            int r = readInt(dis) - 1;
            int totalLen = a + b;
            int diff = r - l;
            int answer;
            if (diff >= 2 * totalLen) {
                answer = Math.max(a + 1, 2 * a - b);
            } else {
                r -= totalLen * (l / totalLen);
                l %= totalLen;
                answer = computeDiff(a, b, l, r);
            }
            System.out.println(answer);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    static int readInt(DataInputStream dis) throws IOException {
        int num = 0;
        int c;
        while ((c = dis.read()) != -1 && (c < '0' || c > '9') && c != '-') ;
        boolean negative = false;
        if (c == '-') {
            negative = true;
            c = dis.read();
        }
        do {
            num = num * 10 + (c - '0');
        } while ((c = dis.read()) >= '0' && c <= '9');
        return negative ? -num : num;
    }

    static int computeDiff(int a, int b, int l, int r) {
        int first = b < a ? b : a - 1;
        int last = a - 1;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < a; i++) {
            sb.append((char) ('a' + i));
        }
        char ch = l < a ? sb.charAt(last) : sb.charAt(first);
        for (int i = 0; i < b; i++) {
            sb.append(ch);
        }
        boolean[] usedLetters = new boolean[30];
        for (int i = 0; i < a; i++) {
            usedLetters[sb.charAt(sb.length() - i - 1) - 'a'] = true;
        }
        int ptr = 0;
        for (int i = 0; i < a; i++) {
            while (usedLetters[ptr]) ptr++;
            sb.append((char) ('a' + ptr));
            usedLetters[ptr] = true;
        }
        ch = sb.charAt(Math.min(b, a - 1) + a + b);
        for (int i = 0; i < b; i++) {
            sb.append(ch);
        }
        for (int i = 0; i < a + b; i++) {
            sb.append(sb.charAt(i));
        }
        return countUniqueLetters(sb.toString(), l, r);
    }

    static int countUniqueLetters(String s, int l, int r) {
        boolean[] used = new boolean[30];
        for (int i = l; i <= r; i++) {
            used[s.charAt(i) - 'a'] = true;
        }
        int count = 0;
        for (boolean b : used) {
            if (b) count++;
        }
        return count;
    }
}
